import{_ as t,o as n,c as a,ah as r}from"./chunks/framework.C-FRNfAJ.js";const u=JSON.parse('{"title":"Billing","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/coordinateur/facturation.md","filePath":"src/en/guide/coordinateur/facturation.md"}'),o={name:"en/guide/coordinateur/facturation.md"};function s(i,e,d,c,h,l){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="billing" tabindex="-1">Billing <a class="header-anchor" href="#billing" aria-label="Permalink to &quot;Billing&quot;">​</a></h1><p><strong>Finance → Billing</strong> gathers invoices, payments, follow-ups and credit notes. Kura <strong>collects nothing</strong>: payments arrive outside Kura, and you record them there.</p><h2 id="invoices" tabindex="-1">Invoices <a class="header-anchor" href="#invoices" aria-label="Permalink to &quot;Invoices&quot;">​</a></h2><p>Each enrolment gives three invoices, on the dates calculated by the cohort: signature (30%), mid-point (40%), balance (30%). They are <strong>issued as you go</strong>: the first at the agreement&#39;s counter-signature, the others <strong>15 days before their due date</strong>. The reference is <code>FAC-NB-YYYY-XXX</code>; the PDF goes by e-mail to the payer.</p><p>Amounts are <strong>excluding tax</strong>: the invoice carries the exemption mention and the payment details, which the Administrator sets.</p><p>In shared funding, each instalment gives <strong>one invoice per payer</strong>, followed separately. The page also lists invoices for paid events, company quotes and placements.</p><p>The list is filtered by status (<strong>Issued</strong>, <strong>Overdue</strong>, <strong>Paid</strong>, <strong>Cancelled</strong>) and searched by reference, payer or learner.</p><h2 id="recording-a-payment" tabindex="-1">Recording a payment <a class="header-anchor" href="#recording-a-payment" aria-label="Permalink to &quot;Recording a payment&quot;">​</a></h2><p>On an invoice, <strong>Payment</strong> asks for:</p><ul><li>the <strong>amount received</strong> (in FCFA), which can never exceed what remains due;</li><li>the <strong>payment method</strong>: bank transfer, cheque, Mobile Money, card or cash;</li><li>the transaction <strong>reference</strong>;</li><li>the <strong>date</strong> received.</li></ul><p>A <strong>partial</strong> payment is possible. The payer receives an acknowledgement. When the invoice&#39;s balance is reached, it becomes &quot;Paid&quot;.</p><p><strong>Paying restores access</strong>: an account suspended for non-payment is reactivated automatically, in Kura and in Sève.</p><h2 id="chasing" tabindex="-1">Chasing <a class="header-anchor" href="#chasing" aria-label="Permalink to &quot;Chasing&quot;">​</a></h2><p>Kura sends the reminders before the due date (D-15, D-7, D-1) and the day after (D+1) by itself. <strong>The D+7 follow-up is yours</strong>: the <strong>To chase (D+7)</strong> filter lists the invoices concerned. Contact the learner or funder by e-mail or phone, then click <strong>Chased</strong>: the date is kept.</p><table tabindex="0"><thead><tr><th>When</th><th>Who acts</th></tr></thead><tbody><tr><td>D+1</td><td>Kura: reminder</td></tr><tr><td>D+7</td><td><strong>You</strong>: personal follow-up</td></tr><tr><td>D+15</td><td>Kura: the invoice becomes &quot;Overdue&quot;, automatic 15-day moratorium</td></tr><tr><td>D+30</td><td>Kura: suspension of access to Sève</td></tr><tr><td>After D+30</td><td><strong>You</strong>: interview, possible repayment plan, otherwise unenrolment</td></tr></tbody></table><p>The moratorium is <strong>unique</strong> and not renegotiable. When the late payer is the <strong>funder</strong>, the learner is suspended too. For a company&#39;s dedicated cohorts, the suspension concerns the cohort&#39;s enrolments, not the accounts.</p><h2 id="if-a-cohort-changes-or-is-cancelled" tabindex="-1">If a cohort changes or is cancelled <a class="header-anchor" href="#if-a-cohort-changes-or-is-cancelled" aria-label="Permalink to &quot;If a cohort changes or is cancelled&quot;">​</a></h2><ul><li><strong>Change of cohort.</strong> Payments are kept; what remained due on invoices already issued is cancelled by a <strong>cancellation credit note</strong> (<code>AV-NB-YYYY-XXX</code>). The new agreement re-invoices each instalment, deducting what the payer has already paid.</li><li><strong>Cancellation by NextBoxx.</strong> Kura issues a <strong>refund credit note</strong> for 100% of the sums paid. It appears &quot;To refund&quot; under <strong>Credit notes</strong>: once the refund is made, click <strong>Refunded</strong> and give the date.</li><li><strong>Drop-out.</strong> No credit note: see <a href="./inscriptions.html#recording-a-drop-out">Enrolments</a>.</li></ul><h2 id="what-is-invoiced" tabindex="-1">What is invoiced <a class="header-anchor" href="#what-is-invoiced" aria-label="Permalink to &quot;What is invoiced&quot;">​</a></h2><p>Only certain events trigger an invoice: the schedule&#39;s instalments, registration for a paid event, an accepted company quote, a confirmed placement.</p>',20)])])}const p=t(o,[["render",s]]);export{u as __pageData,p as default};
